?>"></div><div class="col-md-6"><label class="form-label">Gender</label><select class="form-select" name="gender"><option value="">Select gender</option><?php $__currentLoopData = ['male'=>'Male','female'=>'Female','other'=>'Other']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $value=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($value); ?>" <?php if(old('gender',$customer->gender)===$value): echo 'selected'; endif; ?>><?php echo e($label); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="is_active" value="1" <?php if(old('is_active',$customer->is_active)): echo 'checked'; endif; ?>> Customer account is active</label></div></div></div></div><div class="col-xl-4"><div class="panel"><div class="panel-heading mb-3">User profile</div><div class="media-preview mb-3" data-media-preview="customer-profile"><?php if($customer->profileMedia): ?><img src="<?php echo e($customer->profileMedia->url); ?>" alt="Profile image"><?php else: ?><i class="bi bi-person fs-1"></i><?php endif; ?></div><input type="hidden" id="customer-profile" name="profile_media_id" value="<?php echo e(old('profile_media_id',$customer->profile_media_id)); ?>"><button type="button" class="btn btn-outline-primary w-100" data-media-picker-target="customer-profile"><i class="bi bi-images me-1"></i>Choose profile image</button><div class="small text-muted mt-2" data-media-label="customer-profile">Use the Media Library for a square profile image.</div></div></div></div><div class="mt-4"><a href="<?php echo e(route('admin.customers.index')); ?>" class="btn btn-light">Cancel</a><button class="btn text-white ms-2" style="background:var(--brand)"><?php echo e($editing ? 'Update customer' : 'Create customer'); ?></button></div></form>
